import * as T from './three.module.js';
import {fetchWeaponAsset,weaponAssetURL} from './weapon-assets.js';
import {decodeGoldSrcAsset,loadGoldSrc} from './goldsrc-model.js';
import {MapNavigation} from './map-navigation.js';
export const MAPS=[{key:'ascent',name:'亚海悬城',en:'ASCENT',color:'#c7b9a0'},{key:'pearl',name:'深海遗珠',en:'PEARL',color:'#91b8ce'},{key:'lotus',name:'莲华古城',en:'LOTUS',color:'#b4bf96'},{key:'sunset',name:'日落之城',en:'SUNSET',color:'#deb2a5'},{key:'fracture',name:'裂变峡谷',en:'FRACTURE',color:'#b8c5a1'},{key:'breeze',name:'微风岛屿',en:'BREEZE',color:'#90cad1'},{key:'training',name:'空岛街区',en:'TRAINING',color:'#c0baa7'}];
export async function loadNativeMap(key,{onProgress=()=>{},renderer}={}){
 const base='./assets/maps/'+key+'/',buffer=await fetchWeaponAsset(base+'map.json.gz',{onProgress,timeout:60000}),plain=await decodeGoldSrcAsset(buffer),data=JSON.parse(new TextDecoder().decode(plain)),group=new T.Group(),meshes=[],textures=[],materials=[],geometries=[];group.name='native-map-'+key;
 try {
 const maps=await Promise.all(data.textures.map(async t=>{if(!t.file)return null;const tex=await new T.TextureLoader().loadAsync(weaponAssetURL(base+t.file));tex.colorSpace=T.SRGBColorSpace;tex.flipY=false;tex.wrapS=tex.wrapT=T.RepeatWrapping;tex.anisotropy=Math.min(8,renderer?.capabilities?.getMaxAnisotropy?.()||1);textures.push(tex);return tex;}));
 for(const m of data.meshes){const g=new T.BufferGeometry();for(const[name,values,n]of [['position',m.positions,3],['normal',m.normals,3],['uv',m.uv,2],['color',m.colors,3]])g.setAttribute(name,new T.Float32BufferAttribute(values,n));g.computeBoundingSphere();const t=data.textures[m.texture],material=new T.MeshBasicMaterial({map:maps[m.texture],vertexColors:true,color:maps[m.texture]?0xffffff:0xb8b5ae,side:T.DoubleSide,alphaTest:t.alpha?.5:0,toneMapped:false});const mesh=new T.Mesh(g,material);group.add(mesh);meshes.push(mesh);materials.push(material);geometries.push(g);}
 // Repeated static props share one mesh and texture bank through instancing.
 const props=new Map();for(const p of data.props){if(!props.has(p.file))props.set(p.file,[]);props.get(p.file).push(p);}
 for(const[file,list]of props){try{const parsed=await loadGoldSrc(base+file),rig=parsed.instantiate({world:true});rig.sample(0,0);rig.model.updateMatrixWorld(true);for(const m of rig.meshes){const g=m.geometry.clone(),position=g.attributes.position,v=new T.Vector3();for(let i=0;i<position.count;i++){m.getVertexPosition(i,v).applyMatrix4(m.matrixWorld);position.setXYZ(i,v.x,v.y,v.z);}g.deleteAttribute('skinIndex');g.deleteAttribute('skinWeight');g.computeVertexNormals();const im=new T.InstancedMesh(g,m.material,list.length);im.frustumCulled=false;list.forEach((p,i)=>{const transform=new T.Matrix4().compose(new T.Vector3(...p.position),new T.Quaternion().setFromEuler(new T.Euler(0,p.angles[1]*Math.PI/180,0)),new T.Vector3(1,1,1));im.setMatrixAt(i,transform);});group.add(im);geometries.push(g);}geometries.push(...rig.meshes.map(m=>m.geometry));materials.push(...rig.meshes.map(m=>m.material));textures.push(...rig.meshes.map(m=>m.material.map).filter(Boolean));rig.skeleton.dispose();}catch(e){console.warn('Map prop skipped',file,e.message);}}
 let sky=null;if(data.sky.length===6){const faces=['rt','lf','up','dn','bk','ft'].map(s=>data.sky.find(f=>f.endsWith(s+'.webp')));if(faces.every(Boolean)){sky=await new T.CubeTextureLoader().loadAsync(faces.map(f=>weaponAssetURL(base+f)));sky.colorSpace=T.SRGBColorSpace;textures.push(sky);}}
 const navigation=new MapNavigation(data);data.sites=data.sites.map(s=>navigation.safePoint(s));for(const side of ['attack','defend'])data.spawns[side]=data.spawns[side].map(s=>navigation.safePoint(s));return {key,data,group,meshes,navigation,sky,dispose(){group.removeFromParent();new Set(geometries).forEach(g=>g.dispose());new Set(materials).forEach(m=>m.dispose());new Set(textures).forEach(t=>t.dispose());}};
 }catch(e){new Set(geometries).forEach(g=>g.dispose());new Set(materials).forEach(m=>m.dispose());new Set(textures).forEach(t=>t.dispose());throw e;}
}
